                    A=C[0];a=next(iter(A));b=next(iter(C[1]));allU=set(V)-set(e)
                    cross=[X[tuple(sorted((*e,u,v)))] for u in A for v in allU-A]
                    sol.add(z3.Or(z3.Not(S[tuple(sorted((*e,a)))]),z3.Not(S[tuple(sorted((*e,b)))]),*cross))
                    why='edge-link';break
