                        kill=[X[f] for f in ff if sum(1 for t in combinations(f,3) if t in ti and w>>ti[t]&1)%2]
                        remove=[z3.Not(S[t]) for i,t in enumerate(T) if cyc>>i&1]
                        sol.add(z3.Or(*(kill+remove)));why='H2';break
